  `monto_otorgado` decimal(10,2) NOT NULL,
  `interes` decimal(10,2) NOT NULL,
  `porcentaje_interes` decimal(5,2) DEFAULT NULL COMMENT 'Porcentaje de interes aplicado ej. 21.00',
  `total` decimal(10,2) NOT NULL,
  `saldo_pendiente` decimal(12,2) DEFAULT NULL,
