  `plazos` int NOT NULL,
  `valor_ficha` decimal(10,2) NOT NULL,
  `dias_pago` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tabla_amortizacion` json DEFAULT NULL,
  `estado` enum('Activo','Finalizado','Cancelado','EnMora','CerradoSinRenovacion') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Activo',
  `es_personalizado` tinyint(1) NOT NULL DEFAULT '0',
  `es_adicional` tinyint(1) NOT NULL DEFAULT '0',
  `dias_mora_cache` int NOT NULL DEFAULT '0',
  `ubicacion_expediente` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
