  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`num_prog`),
  KEY `creditos_id_cliente_foreign` (`id_cliente`),
  KEY `creditos_id_asesor_foreign` (`id_asesor`),
  KEY `creditos_id_grupo_foreign` (`id_grupo`),
  KEY `creditos_credito_padre_id_foreign` (`credito_padre_id`),
